PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS roles (id INTEGER PRIMARY KEY, key TEXT NOT NULL UNIQUE, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', system_role INTEGER NOT NULL DEFAULT 0 CHECK(system_role IN (0,1)));
CREATE TABLE IF NOT EXISTS permissions (id INTEGER PRIMARY KEY, key TEXT NOT NULL UNIQUE, description TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS role_permissions (role_id INTEGER NOT NULL REFERENCES roles(id) ON DELETE CASCADE, permission_id INTEGER NOT NULL REFERENCES permissions(id) ON DELETE CASCADE, PRIMARY KEY(role_id,permission_id));
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, username TEXT NOT NULL UNIQUE COLLATE NOCASE, email TEXT UNIQUE COLLATE NOCASE, password_hash TEXT NOT NULL, password_salt TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)), must_change_password INTEGER NOT NULL DEFAULT 0 CHECK(must_change_password IN (0,1)), last_login_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS user_roles (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, role_id INTEGER NOT NULL REFERENCES roles(id), PRIMARY KEY(user_id,role_id));
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS schools (id INTEGER PRIMARY KEY CHECK(id=1), name TEXT NOT NULL, code TEXT, address TEXT, phone TEXT, email TEXT, logo_path TEXT, motto TEXT, currency TEXT NOT NULL DEFAULT 'NGN', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS academic_sessions (id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE, starts_on TEXT, ends_on TEXT, active INTEGER NOT NULL DEFAULT 0 CHECK(active IN (0,1)), CHECK(ends_on IS NULL OR starts_on IS NULL OR ends_on>=starts_on));
CREATE TABLE IF NOT EXISTS terms (id INTEGER PRIMARY KEY, session_id INTEGER NOT NULL REFERENCES academic_sessions(id) ON DELETE RESTRICT, name TEXT NOT NULL CHECK(name IN ('First Term','Second Term','Third Term')), starts_on TEXT, ends_on TEXT, active INTEGER NOT NULL DEFAULT 0 CHECK(active IN (0,1)), UNIQUE(session_id,name));
CREATE UNIQUE INDEX IF NOT EXISTS one_active_session ON academic_sessions(active) WHERE active=1;
CREATE UNIQUE INDEX IF NOT EXISTS one_active_term_per_session ON terms(session_id,active) WHERE active=1;
CREATE TABLE IF NOT EXISTS classes (id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE, level TEXT NOT NULL CHECK(level IN ('Nursery','Primary','Junior Secondary','Senior Secondary')), sort_order INTEGER NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)));
CREATE TABLE IF NOT EXISTS class_arms (id INTEGER PRIMARY KEY, class_id INTEGER NOT NULL REFERENCES classes(id) ON DELETE RESTRICT, name TEXT NOT NULL, capacity INTEGER CHECK(capacity IS NULL OR capacity>0), UNIQUE(class_id,name));
CREATE TABLE IF NOT EXISTS students (id TEXT PRIMARY KEY, admission_number TEXT NOT NULL UNIQUE, first_name TEXT NOT NULL, middle_name TEXT NOT NULL DEFAULT '', surname TEXT NOT NULL, gender TEXT NOT NULL CHECK(gender IN ('Female','Male','Other')), date_of_birth TEXT, state_of_origin TEXT, lga TEXT, nationality TEXT NOT NULL DEFAULT 'Nigerian', address TEXT, photograph_path TEXT, previous_school TEXT, admission_date TEXT NOT NULL, session_id INTEGER NOT NULL REFERENCES academic_sessions(id), class_arm_id INTEGER NOT NULL REFERENCES class_arms(id), status TEXT NOT NULL DEFAULT 'Active' CHECK(status IN ('Active','Graduated','Transferred','Withdrawn','Deceased')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_students_class ON students(class_arm_id,status);
CREATE TABLE IF NOT EXISTS parents (id TEXT PRIMARY KEY, user_id TEXT UNIQUE REFERENCES users(id) ON DELETE SET NULL, first_name TEXT NOT NULL, surname TEXT NOT NULL, phone TEXT NOT NULL, email TEXT, address TEXT, occupation TEXT);
CREATE TABLE IF NOT EXISTS student_parents (student_id TEXT NOT NULL REFERENCES students(id) ON DELETE CASCADE, parent_id TEXT NOT NULL REFERENCES parents(id) ON DELETE CASCADE, relationship TEXT NOT NULL, primary_contact INTEGER NOT NULL DEFAULT 0 CHECK(primary_contact IN (0,1)), PRIMARY KEY(student_id,parent_id));
CREATE TABLE IF NOT EXISTS staff (id TEXT PRIMARY KEY, user_id TEXT UNIQUE REFERENCES users(id) ON DELETE SET NULL, staff_number TEXT NOT NULL UNIQUE, first_name TEXT NOT NULL, surname TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('Teacher','Non-teaching')), phone TEXT, email TEXT, hired_on TEXT, active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)));
CREATE TABLE IF NOT EXISTS teacher_assignments (id INTEGER PRIMARY KEY, staff_id TEXT NOT NULL REFERENCES staff(id) ON DELETE CASCADE, class_arm_id INTEGER NOT NULL REFERENCES class_arms(id), subject_id INTEGER, UNIQUE(staff_id,class_arm_id,subject_id));
CREATE TABLE IF NOT EXISTS subjects (id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE, code TEXT, active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS student_portal_link (student_id TEXT PRIMARY KEY REFERENCES students(id) ON DELETE CASCADE, user_id TEXT NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS parent_portal_link (parent_id TEXT PRIMARY KEY REFERENCES parents(id) ON DELETE CASCADE, user_id TEXT NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS stakeholder_schools (id TEXT PRIMARY KEY, name TEXT NOT NULL, address TEXT, phone TEXT NOT NULL, email TEXT, representative TEXT NOT NULL, user_id TEXT UNIQUE REFERENCES users(id) ON DELETE SET NULL, status TEXT NOT NULL DEFAULT 'Pending' CHECK(status IN ('Pending','Approved','Rejected','Inactive')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS stakeholder_registrations (id TEXT PRIMARY KEY, stakeholder_id TEXT NOT NULL REFERENCES stakeholder_schools(id), first_name TEXT NOT NULL, surname TEXT NOT NULL, date_of_birth TEXT, gender TEXT CHECK(gender IN ('Female','Male','Other')), exam_type TEXT NOT NULL DEFAULT 'WAEC' CHECK(exam_type IN ('WAEC','NECO','JAMB','BECE','CASS','Common Entrance','WAEC & NECO','WAEC, NECO & JAMB')), photograph_path TEXT, documents_json TEXT NOT NULL DEFAULT '[]', requested_session_id INTEGER NOT NULL REFERENCES academic_sessions(id), assigned_admission_number TEXT UNIQUE, assigned_class_arm_id INTEGER REFERENCES class_arms(id), status TEXT NOT NULL DEFAULT 'Pending' CHECK(status IN ('Pending','Approved','Rejected')), decision_note TEXT, amount_paid_kobo INTEGER NOT NULL DEFAULT 0 CHECK(amount_paid_kobo>=0), amount_due_kobo INTEGER NOT NULL DEFAULT 0 CHECK(amount_due_kobo>=0), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_stakeholder_reg_owner ON stakeholder_registrations(stakeholder_id,status);
CREATE TABLE IF NOT EXISTS fee_categories (id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE, description TEXT, active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS fee_assignments (id TEXT PRIMARY KEY, category_id INTEGER NOT NULL REFERENCES fee_categories(id), session_id INTEGER NOT NULL REFERENCES academic_sessions(id), term_id INTEGER REFERENCES terms(id), class_arm_id INTEGER REFERENCES class_arms(id), student_id TEXT REFERENCES students(id), amount_kobo INTEGER NOT NULL CHECK(amount_kobo>=0), due_on TEXT, CHECK(class_arm_id IS NOT NULL OR student_id IS NOT NULL));
CREATE INDEX IF NOT EXISTS idx_fee_assignments_student ON fee_assignments(student_id,session_id,term_id);
CREATE TABLE IF NOT EXISTS discounts (id TEXT PRIMARY KEY, student_id TEXT NOT NULL REFERENCES students(id), session_id INTEGER NOT NULL REFERENCES academic_sessions(id), term_id INTEGER REFERENCES terms(id), amount_kobo INTEGER NOT NULL CHECK(amount_kobo>=0), reason TEXT NOT NULL, approved_by TEXT REFERENCES users(id), approved_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS payments (id TEXT PRIMARY KEY, idempotency_key TEXT NOT NULL UNIQUE, receipt_number TEXT NOT NULL UNIQUE, student_id TEXT NOT NULL REFERENCES students(id), session_id INTEGER NOT NULL REFERENCES academic_sessions(id), term_id INTEGER REFERENCES terms(id), amount_kobo INTEGER NOT NULL CHECK(amount_kobo>0), method TEXT NOT NULL CHECK(method IN ('Cash','Bank Transfer','POS','Cheque','Other')), reference TEXT UNIQUE, received_by TEXT NOT NULL REFERENCES users(id), status TEXT NOT NULL DEFAULT 'Verified' CHECK(status IN ('Pending','Verified','Reversed')), paid_at TEXT NOT NULL, notes TEXT, reversed_by TEXT REFERENCES users(id), reversal_reason TEXT, reversed_at TEXT);
CREATE TABLE IF NOT EXISTS payment_allocations (payment_id TEXT NOT NULL REFERENCES payments(id), fee_assignment_id TEXT NOT NULL REFERENCES fee_assignments(id), amount_kobo INTEGER NOT NULL CHECK(amount_kobo>0), PRIMARY KEY(payment_id,fee_assignment_id));
CREATE TABLE IF NOT EXISTS assessment_components (id INTEGER PRIMARY KEY, session_id INTEGER NOT NULL REFERENCES academic_sessions(id), term_id INTEGER NOT NULL REFERENCES terms(id), name TEXT NOT NULL, max_score REAL NOT NULL CHECK(max_score>0), weight REAL NOT NULL CHECK(weight>=0), UNIQUE(session_id,term_id,name));
CREATE TABLE IF NOT EXISTS grading_scales (id INTEGER PRIMARY KEY, name TEXT NOT NULL, min_score REAL NOT NULL, max_score REAL NOT NULL, grade TEXT NOT NULL, remark TEXT NOT NULL, CHECK(min_score<=max_score));
CREATE TABLE IF NOT EXISTS results (id TEXT PRIMARY KEY, student_id TEXT NOT NULL REFERENCES students(id), subject_id INTEGER NOT NULL REFERENCES subjects(id), component_id INTEGER NOT NULL REFERENCES assessment_components(id), score REAL NOT NULL CHECK(score>=0), entered_by TEXT NOT NULL REFERENCES users(id), status TEXT NOT NULL DEFAULT 'Draft' CHECK(status IN ('Draft','Submitted','Approved')), updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(student_id,subject_id,component_id));
CREATE TABLE IF NOT EXISTS report_cards (id TEXT PRIMARY KEY, student_id TEXT NOT NULL REFERENCES students(id), session_id INTEGER NOT NULL REFERENCES academic_sessions(id), term_id INTEGER NOT NULL REFERENCES terms(id), status TEXT NOT NULL DEFAULT 'Draft' CHECK(status IN ('Draft','Published')), promotion_decision TEXT CHECK(promotion_decision IN ('Promoted','Repeated','Graduated','Transferred')), class_teacher_comment TEXT, head_teacher_comment TEXT, published_by TEXT REFERENCES users(id), published_at TEXT, UNIQUE(student_id,session_id,term_id));
CREATE TRIGGER IF NOT EXISTS report_card_promotion_only_third_term BEFORE UPDATE OF promotion_decision ON report_cards WHEN NEW.promotion_decision IS NOT NULL AND (SELECT name FROM terms WHERE id=NEW.term_id)<>'Third Term' BEGIN SELECT RAISE(ABORT,'Promotion or repetition can only be recorded on Third Term report cards.'); END;
CREATE TRIGGER IF NOT EXISTS report_card_promotion_only_third_term_insert BEFORE INSERT ON report_cards WHEN NEW.promotion_decision IS NOT NULL AND (SELECT name FROM terms WHERE id=NEW.term_id)<>'Third Term' BEGIN SELECT RAISE(ABORT,'Promotion or repetition can only be recorded on Third Term report cards.'); END;
CREATE TABLE IF NOT EXISTS promotion_records (id INTEGER PRIMARY KEY, student_id TEXT NOT NULL REFERENCES students(id), session_id INTEGER NOT NULL REFERENCES academic_sessions(id), decision TEXT NOT NULL CHECK(decision IN ('Promoted','Repeated','Graduated','Transferred')), decided_by TEXT NOT NULL REFERENCES users(id), decided_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(student_id,session_id));
CREATE TABLE IF NOT EXISTS attendance (id INTEGER PRIMARY KEY, student_id TEXT NOT NULL REFERENCES students(id), class_arm_id INTEGER NOT NULL REFERENCES class_arms(id), marked_by TEXT NOT NULL REFERENCES users(id), attendance_date TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('Present','Absent','Late','Excused')), note TEXT, UNIQUE(student_id,attendance_date));
CREATE TABLE IF NOT EXISTS resources (id TEXT PRIMARY KEY, title TEXT NOT NULL, description TEXT, resource_type TEXT NOT NULL DEFAULT 'Learning material', stored_path TEXT NOT NULL, original_name TEXT NOT NULL, mime_type TEXT NOT NULL, size_bytes INTEGER NOT NULL CHECK(size_bytes>=0), uploaded_by TEXT NOT NULL REFERENCES users(id), class_arm_id INTEGER REFERENCES class_arms(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS announcements (id TEXT PRIMARY KEY, title TEXT NOT NULL, body TEXT NOT NULL, audience TEXT NOT NULL DEFAULT 'All', published_by TEXT NOT NULL REFERENCES users(id), published_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, expires_at TEXT);
CREATE TABLE IF NOT EXISTS messages (id TEXT PRIMARY KEY, sender_id TEXT NOT NULL REFERENCES users(id), recipient_id TEXT NOT NULL REFERENCES users(id), subject TEXT, body TEXT NOT NULL, sent_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, read_at TEXT);
CREATE TABLE IF NOT EXISTS notifications (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, title TEXT NOT NULL, body TEXT NOT NULL, read_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS timetable_entries (id INTEGER PRIMARY KEY, class_arm_id INTEGER NOT NULL REFERENCES class_arms(id), subject_id INTEGER NOT NULL REFERENCES subjects(id), staff_id TEXT REFERENCES staff(id), weekday INTEGER NOT NULL CHECK(weekday BETWEEN 1 AND 5), starts_at TEXT NOT NULL, ends_at TEXT NOT NULL, room TEXT);
CREATE TABLE IF NOT EXISTS school_events (id INTEGER PRIMARY KEY, title TEXT NOT NULL, description TEXT, starts_at TEXT NOT NULL, ends_at TEXT, location TEXT);
CREATE TABLE IF NOT EXISTS expense_categories (id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE, active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS expenses (id TEXT PRIMARY KEY, category TEXT NOT NULL, description TEXT NOT NULL, amount_kobo INTEGER NOT NULL CHECK(amount_kobo>0), spent_on TEXT NOT NULL, recorded_by TEXT NOT NULL REFERENCES users(id));
CREATE TABLE IF NOT EXISTS audit_logs (id INTEGER PRIMARY KEY, actor_id TEXT REFERENCES users(id), action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT, details_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_audit_created ON audit_logs(created_at DESC);
CREATE TABLE IF NOT EXISTS app_settings (key TEXT PRIMARY KEY, value_json TEXT NOT NULL, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS backup_history (id INTEGER PRIMARY KEY, file_path TEXT NOT NULL, size_bytes INTEGER NOT NULL, checksum TEXT NOT NULL, created_by TEXT REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, verified INTEGER NOT NULL DEFAULT 0 CHECK(verified IN (0,1)));
CREATE TABLE IF NOT EXISTS audit_events (id INTEGER PRIMARY KEY, event_type TEXT NOT NULL, occurred_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, details_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS student_status_history (id INTEGER PRIMARY KEY, student_id TEXT NOT NULL REFERENCES students(id), old_status TEXT NOT NULL, new_status TEXT NOT NULL, effective_on TEXT NOT NULL, reason TEXT NOT NULL, changed_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS class_subjects (id INTEGER PRIMARY KEY, class_arm_id INTEGER NOT NULL REFERENCES class_arms(id) ON DELETE CASCADE, subject_id INTEGER NOT NULL REFERENCES subjects(id), UNIQUE(class_arm_id,subject_id));
CREATE TABLE IF NOT EXISTS backup_schedule (id INTEGER PRIMARY KEY CHECK(id=1), enabled INTEGER NOT NULL DEFAULT 0, interval_days INTEGER NOT NULL DEFAULT 7, destination TEXT, last_run_at TEXT);
CREATE TABLE IF NOT EXISTS payment_receipts (id TEXT PRIMARY KEY,uploaded_by TEXT NOT NULL REFERENCES users(id),student_id TEXT REFERENCES students(id),registration_id TEXT REFERENCES stakeholder_registrations(id),purpose TEXT NOT NULL CHECK(purpose IN ('examinations','school-fees')),amount_kobo INTEGER NOT NULL CHECK(amount_kobo>0),paid_on TEXT NOT NULL,bank_reference TEXT,stored_path TEXT NOT NULL,original_name TEXT NOT NULL,mime_type TEXT NOT NULL,size_bytes INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,CHECK((student_id IS NOT NULL AND registration_id IS NULL) OR (student_id IS NULL AND registration_id IS NOT NULL)));
CREATE INDEX IF NOT EXISTS idx_payment_receipts_uploader ON payment_receipts(uploaded_by,created_at);
